import{_ as a,c as t,o as l,ah as i}from"./chunks/framework.BxT5r71R.js";const d=JSON.parse('{"title":"前言","titleTemplate":"Management 2 本篇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/Management2/PART0/1_前言.md","filePath":"zh-cn/Management2/PART0/1_前言.md"}'),n={name:"zh-cn/Management2/PART0/1_前言.md"};function p(_,e,r,o,s,c){return l(),t("div",null,[...e[0]||(e[0]=[i('<h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>如果您是冲着那个颇有气势的副标题（日本音乐能否跨过走向世界的墙）而来的，读到这里或许会有些扫兴：事实上，如今日本与世界音乐行业之间，并不存在什么“墙”。只要说清楚这个前提，这篇前言就算完成了任务。不过，还是再详细聊聊吧。首先，做个自我介绍。</p><p>初次见面的各位，你们好；已经认识我的各位，感谢你们一直以来的支持。我姓日高，是BMSG公司的代表董事兼CEO。我从十几岁起就以SKY-HI的艺名从事说唱音乐，2021年起，还担任BE:FIRST等男子组合的制作人。每天兼顾这三重身份，与其说充满刺激，不如说不安与幸福如绳股般交织。真是段奇特的人生啊。</p><p>此外，我还以日高光启的名字，作为AAA成员活动了约20年（组合目前暂停活动）。再往前追溯，我从初中起就开始了演艺活动。这一路走来，我的经历包括：</p><ul><li>在日本规模最大的经纪公司做偶像练习生</li><li>做乐队成员</li><li>在另一家大型经纪公司做练习生</li><li>作为AAA成员活动</li><li>做地下说唱歌手</li><li>担任独立厂牌负责人</li><li>创办BMSG</li><li>从事制作人工作</li></ul><p>就这样，我辗转于音乐行业和演艺圈的不同领域。尤其是以说唱歌手和作曲家的身份，我想，日本国内与音乐相关的公司，无论属于独立音乐体系还是主流唱片体系，我几乎都合作过。我还与海外艺人共同创作作品，开展世界巡演……越写越觉得，自己还真是折腾不够，什么都做过啊……</p><p>本来，艺人专注于一件事，默默打磨自己的风格，才更酷。不过，也不知是好是坏，我这闲不住的性格，倒是帮我看清了音乐行业的更多细节。</p><p>最出乎我意料的是，在我尝试了这么多事情的这段时间里……也就是自己创业前的约20年间，日本音乐产业的根本结构和演艺圈的积习，竟然一直没有改变。</p><p>日本与世界的音乐圈之间，并没有什么“墙”，只有“时差”。而互联网这项发明，无论好坏，恰恰能消除世界各地的“时差”。所以，日本音乐走向世界各地听众的道路，早就存在了。或者说，实际上已经有很多人在听了。</p><p>为什么大家没能一起走上这条路？为什么BMSG相信自己能走通，正兴致勃勃地做着准备？希望这本书能把这些事情讲清楚……如果还能改变您心中的常识，而这份改变又能传递开来、不断扩展，那么，我们的足迹自然会遍及世界。好了，准备好护照吧！</p>',10)])])}const A=a(n,[["render",p]]);export{d as __pageData,A as default};
